import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { initializeApp } from 'firebase/app';
import { getAuth, signInAnonymously, signInWithCustomToken, onAuthStateChanged } from 'firebase/auth';
import { getFirestore, doc, setDoc, deleteDoc, onSnapshot } from 'firebase/firestore';

// Set Firebase logging to Debug for visibility in the console
import { setLogLevel } from 'firebase/app';
setLogLevel('debug');

// --- DataDisplay Component (Child 2) ---
// This child component receives submitted data and a reset handler from the parent.
const DataDisplay = ({ submittedData, onReset }) => {
    if (!submittedData) {
        return (
            <div className="flex items-center justify-center bg-white p-6 rounded-xl shadow-xl border border-dashed border-gray-300 h-full min-h-[300px]">
                <p className="text-gray-500 italic text-center">
                    Submit the form to see the data displayed here. (Data will be saved persistently)
                </p>
            </div>
        );
    }

    const data = [
        { key: 'Full Name', value: submittedData.name },
        { key: 'Email', value: submittedData.email },
        { key: 'Role', value: submittedData.role },
    ];

    return (
        <div className="bg-gray-50 p-6 rounded-xl shadow-2xl w-full border border-indigo-100">
            <h2 className="text-2xl font-extrabold text-indigo-700 mb-6 flex items-center">
                <svg className="w-6 h-6 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944v.004M12 20.944v.004A11.955 11.955 0 016.382 17.01C4.301 15.006 3 12.308 3 9.5a9.5 9.5 0 0119-3.5c-.328.601-.68 1.155-1.05 1.666"></path></svg>
                Saved Data (from Firestore)
            </h2>
            <dl className="space-y-3">
                {data.map(({ key, value }) => (
                    <div key={key} className="flex justify-between items-center py-2 border-b last:border-b-0 border-indigo-100">
                        <dt className="text-sm font-medium text-gray-500">{key}:</dt>
                        <dd className="text-lg font-semibold text-gray-900">{value}</dd>
                    </div>
                ))}
            </dl>
            <button
                onClick={onReset}
                className="mt-6 w-full py-2 px-4 border border-red-600 rounded-lg text-sm font-semibold text-red-600 bg-white hover:bg-red-50 transition duration-300 ease-in-out focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2"
            >
                Clear Saved Data
            </button>
            <p className="mt-4 text-xs text-gray-500 truncate">
                User ID: {submittedData.userId}
            </p>
        </div>
    );
};

export default DataDisplay;