import UserForm from "./UserForm";
import React, { useState, useCallback, useMemo, useEffect } from 'react';


import DataDisplay from "./DataDisplay";

// Correct Firestore imports



const Contact = () => {


    <form name="contact" netlify netlify-honeypot="bot-field" hidden>
        <input type="text" name="name" />
        <input type="email" name="email" />
        <input type="tel" name="phonenumber" />
        <textarea name="message"></textarea>
    </form>

    return (
        <div className="page">
            <div className="card container">
                <h1 className="textcolor">Contact Us</h1>

                <div style={{ display: 'flex', flexWrap: 'wrap', maxWidth: '100%', padding: '2px' }}>
                    <div className="padded-text">

                        Have questions or feedback? We'd love to hear from you!
                        Please call me, 917-209-2291
                        email:  edchenstudio2020@gmail.com

                        <br></br>
                        <form name="contact" method="post">
                            <input type="hidden" name="form-name" value="contact" />
                            <p>
                                <label>Your Name: <input type="text" name="name" /></label>
                            </p>
                            <p>
                                <label>Your Email: <input type="email" name="email" /></label>
                            </p>
                            <p>
                                <label>Phone Number: <input type="tel" name="phonenumber" placeholder="(555) 123-4567" maxlength="14" /></label>
                            </p>
                            <p>
                                <label>Message: <textarea name="message"></textarea></label>
                            </p>
                            <p>
                                <button type="submit">Send</button>
                            </p>
                        </form>


                    </div>
                </div>

            </div>
        </div>
    );

};

export default Contact;